{"implementation":"def solve(case):
    import math
    from numbers import Real

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field type")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")

    required = set(required_symbols)
    by_id = {}
    order = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("missing required node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int):
            raise ValueError("depth must be an integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, Real) or not math.isfinite(float(utility)):
            raise ValueError("utility must be a finite number")
        by_id[node_id] = node
        order.append(node_id)

    roots = [node_id for node_id in order if by_id[node_id]["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    for node_id in order:
        parent = by_id[node_id]["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("parent must reference an existing node")

    children = {node_id: [] for node_id in order}
    for node_id in order:
        parent = by_id[node_id]["parent"]
        if parent is not None:
            children[parent].append(node_id)

    state = {node_id: 0 for node_id in order}
    def visit(node_id):
        if state[node_id] == 1:
            raise ValueError("tree contains a cycle")
        if state[node_id] == 2:
            return
        state[node_id] = 1
        for child_id in children[node_id]:
            visit(child_id)
        state[node_id] = 2
    visit(roots[0])
    if any(value != 2 for value in state.values()):
        raise ValueError("tree is disconnected")

    removed = set()
    removal_order = []
    candidates = sorted(order, key=lambda node_id: (-by_id[node_id]["depth"], node_id))
    for node_id in candidates:
        node = by_id[node_id]
        if node_id == roots[0] or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id not in removed for child_id in children[node_id]):
            continue
        remaining_symbols = {
            by_id[other_id]["symbol"]
            for other_id in order
            if other_id not in removed and other_id != node_id
        }
        if not required.issubset(remaining_symbols):
            continue
        removed.add(node_id)
        removal_order.append(node_id)

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": sorted(node_id for node_id in order if node_id not in removed),
    }"}
